WITH lines AS (SELECT id, host, log_ts, level, status_code, key, value FROM app_logs LATERAL VIEW OUTER EXPLODE(context) x AS key, value) SELECT host, log_ts, status_code, CUME_DIST() OVER (PARTITION BY level, key ORDER BY status_code) AS status_code_cume_dist, ROUND(status_code / SUM(status_code) OVER (PARTITION BY host, key), 4) AS status_code_share, MAX(status_code) OVER (PARTITION BY level) AS level_max_status_code FROM lines WHERE key = 'trace';
